*{box-sizing:border-box} :root{--red:#ed2947;--pink:#ff536a;--cream:#f6f1ee;--muted:#a19aa8;--panel:rgba(17,14,24,.76)} html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#100d18;color:var(--cream);font-family:'DM Sans',sans-serif} button{font:inherit;color:inherit} .game-shell{position:relative;width:100vw;height:100dvh;min-height:480px;overflow:hidden;background:#171321} canvas{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(13,10,19,.76) 0%,transparent 23%,transparent 70%,rgba(13,10,19,.68) 100%),radial-gradient(ellipse at 50% 45%,transparent 40%,rgba(8,7,13,.4) 100%)}.topbar{position:absolute;left:4.15%;right:4.15%;top:26px;height:44px;display:flex;align-items:center;justify-content:space-between;z-index:2}.brand{display:flex;align-items:center;gap:12px;color:inherit;text-decoration:none}.brand-mark{height:36px;width:36px;background:var(--red);font:900 24px/36px 'Barlow Condensed',sans-serif;text-align:center;clip-path:polygon(0 0,100% 0,100% 74%,50% 100%,0 74%);text-shadow:0 2px 3px #891427}.brand-name{font:800 16px 'Barlow Condensed',sans-serif;letter-spacing:1.6px}.brand-name span{font-size:11px;color:#c0b9c5;letter-spacing:1.25px;font-weight:600;margin-left:4px}.mission{display:flex;flex-direction:column;position:absolute;left:50%;transform:translateX(-50%);align-items:center;gap:4px}.mission-kicker,.eyebrow{font-size:9px;letter-spacing:1.65px;color:#b7aeba;font-weight:700}.mission-kicker i{display:inline-block;width:4px;height:4px;border-radius:50%;background:var(--red);vertical-align:middle;margin:0 6px}.mission-name{font:600 16px 'Barlow Condensed',sans-serif;letter-spacing:.5px}.sound-button{background:rgba(14,11,19,.48);border:1px solid rgba(255,255,255,.2);height:34px;padding:0 12px;display:flex;gap:8px;align-items:center;border-radius:3px;letter-spacing:1px;font-size:9px;color:#d9d3dc}.sound-button span:first-child{color:#ff5269;font-size:15px}.hud{z-index:2;position:absolute;top:99px;left:4.15%;display:flex;align-items:center;gap:28px}.hero-card{display:flex;align-items:center;gap:12px}.portrait{width:46px;height:46px;background:linear-gradient(140deg,#722236,#251521 67%);border:1px solid rgba(251,77,102,.72);position:relative;display:grid;place-items:center;overflow:hidden;box-shadow:0 0 17px #e7294733}.portrait>span{font:900 36px/.9 'Barlow Condensed',sans-serif;color:#f13a57;z-index:1}.portrait-glow{position:absolute;bottom:-16px;left:4px;width:35px;height:35px;border-radius:50%;background:#ff748577;filter:blur(8px)}.hero-info{min-width:148px;display:flex;flex-direction:column;gap:3px}.hero-info strong{font:700 18px 'Barlow Condensed',sans-serif;letter-spacing:.9px}.health-track{width:160px;height:4px;background:#51424c;margin-top:3px;overflow:hidden}.health-track span{height:100%;width:100%;display:block;background:linear-gradient(90deg,#ff344f,#ff7780);transition:width .25s}.health-label{font-size:10px;font-weight:700;color:#fff}.health-label small{font-size:8px;letter-spacing:1.2px;color:#b0a7b3;font-weight:600}.wave-card,.score-card{border-left:1px solid #ffffff27;padding-left:18px;height:40px;display:flex;flex-direction:column;justify-content:center;gap:1px}.wave-card strong{font:700 21px 'Barlow Condensed',sans-serif}.wave-card strong i{font-size:13px;font-style:normal;color:#a49ba8}.wave-dots{display:flex;gap:3px}.wave-dots span{display:block;width:12px;height:2px;background:#5b505d}.wave-dots .active{background:var(--red)}.score-card strong{font:700 20px 'Barlow Condensed',sans-serif}.score-sub{font-size:7px;letter-spacing:.85px;color:#a79eaa}.score-sub b{color:#ff455d}.objective{position:absolute;z-index:2;left:4.15%;top:178px;display:flex;align-items:center;gap:10px;padding:8px 12px;background:linear-gradient(90deg,rgba(20,15,25,.75),transparent);border-left:2px solid #e63851}.objective-icon{font-size:15px;color:#fc4c65}.objective>span:last-child{display:flex;flex-direction:column;gap:2px}.objective b{font-size:8px;letter-spacing:1.6px;color:#ff6173}.objective small{font-size:10px;color:#e3dce3}.controls-hint{position:absolute;z-index:2;left:50%;bottom:47px;transform:translateX(-50%);display:flex;align-items:center;gap:7px;white-space:nowrap;color:#c7c0ca}.keycap{font:700 9px 'DM Sans',sans-serif;border:1px solid #ffffff52;background:#19141eaa;border-radius:3px;padding:5px 7px;box-shadow:0 2px #ffffff18}.controls-hint small{font-size:8px;letter-spacing:.7px;color:#b6aeb9;margin-right:4px}.hint-divider{height:18px;width:1px;background:#ffffff33;margin:0 6px}.abilities{position:absolute;z-index:2;right:4.2%;bottom:41px;display:flex;gap:7px}.ability{width:87px;height:66px;background:linear-gradient(145deg,rgba(35,28,40,.78),rgba(17,13,22,.86));border:1px solid #ffffff30;position:relative;display:flex;align-items:center;flex-direction:column;justify-content:center;gap:2px;box-shadow:inset 0 1px #ffffff08}.ability-key{position:absolute;top:5px;left:6px;border:1px solid #ffffff3a;border-radius:2px;font:700 8px 'DM Sans';padding:1px 4px;color:#e6dfe7}.ability-icon{font-size:19px;color:#fc405b;line-height:20px;text-shadow:0 0 12px #fa2c51}.dash-icon{font-size:16px}.ability-name{font:700 8px 'Barlow Condensed',sans-serif;letter-spacing:.6px}.ability-cd{font-size:7px;letter-spacing:1px;color:#ff6677}.screen{position:absolute;inset:0;z-index:5;display:flex;align-items:center;justify-content:center;background:rgba(10,8,15,.3);backdrop-filter:blur(2px);transition:opacity .35s}.screen.hidden{opacity:0;pointer-events:none}.intro-card,.end-card{position:relative;width:min(460px,88vw);padding:31px 43px 27px;background:linear-gradient(135deg,rgba(19,15,25,.94),rgba(24,16,27,.88));border:1px solid rgba(255,255,255,.17);text-align:center;box-shadow:0 20px 90px #07050ccc;clip-path:polygon(0 0,96% 0,100% 6%,100% 100%,4% 100%,0 94%)}.intro-card:before,.end-card:before{content:'';position:absolute;left:0;top:0;width:3px;height:78px;background:var(--red)}.intro-top{display:flex;align-items:center;justify-content:center;gap:9px;font-size:8px;font-weight:700;color:#bbb1be;letter-spacing:2px}.red-line{height:1px;width:27px;background:#dd344d}.title-mark{font:900 88px/.82 'Barlow Condensed',sans-serif;letter-spacing:6px;color:#f1304e;text-shadow:0 4px 0 #8e1c32,0 0 35px #f3264b62;margin:20px 0 2px;transform:skew(-5deg)}.subtitle{font:700 17px 'Barlow Condensed',sans-serif;letter-spacing:5.5px}.subtitle span{font-size:11px;color:#aaa0ac;letter-spacing:2px}.intro-divider{display:flex;align-items:center;justify-content:center;gap:10px;margin:17px auto 13px;color:#f73f5b;font-size:12px}.intro-divider i{width:66px;height:1px;background:linear-gradient(90deg,transparent,#9a4252)}.intro-divider i:last-child{transform:rotate(180deg)}.intro-card p,.end-card p{font-size:12px;line-height:1.8;color:#c5bdc8;margin:0 0 19px}.intro-card p b{color:#fff;font-weight:600}.play-button{height:43px;min-width:222px;border:0;background:#e72d49;display:inline-flex;align-items:center;justify-content:space-between;padding:0 15px 0 20px;cursor:pointer;clip-path:polygon(0 0,96% 0,100% 22%,100% 100%,4% 100%,0 78%);font:800 12px 'Barlow Condensed',sans-serif;letter-spacing:1.4px;box-shadow:0 6px 24px #d927454a;transition:background .2s,transform .2s}.play-button:hover{background:#ff405b;transform:translateY(-2px)}.play-button b{font-size:19px;font-weight:500}.start-note{margin-top:17px;font-size:7px;letter-spacing:1.1px;color:#8f8692}.start-note span{color:#f34660;margin:0 4px}.start-character{position:absolute;right:10%;bottom:0;width:170px;height:70%;opacity:.18;pointer-events:none}.start-character:before{content:'';position:absolute;bottom:-30px;left:34px;width:100px;height:260px;background:linear-gradient(160deg,#f72d51,#5b172c 62%,transparent);clip-path:polygon(28% 0,72% 3%,90% 30%,100% 100%,0 93%,14% 34%);filter:drop-shadow(0 0 20px #ed2446)}.start-character:after{content:'';position:absolute;left:64px;bottom:204px;width:54px;height:57px;background:#c47b85;border-radius:48% 47% 42% 42%;box-shadow:0 -10px 0 5px #36202c}.scythe-glint{position:absolute;bottom:130px;right:0;width:180px;height:4px;background:#e8cfd3;transform:rotate(-42deg);box-shadow:0 0 11px #ff3556}.start-caption{position:absolute;bottom:42px;right:5px;display:flex;flex-direction:column;align-items:flex-end;gap:4px;white-space:nowrap}.start-caption span{font-size:8px;color:#fd5367;letter-spacing:1.5px}.start-caption b{font:700 20px 'Barlow Condensed';letter-spacing:1px}.end-card{padding:42px}.end-kicker{font-size:9px;letter-spacing:2px;color:#ff536a;font-weight:700}.end-card h1{font:800 36px/1 'Barlow Condensed';margin:12px 0}.final-score{display:flex;justify-content:space-between;align-items:center;border-block:1px solid #ffffff24;padding:12px 0;margin:20px 0;font-size:9px;letter-spacing:1.2px;color:#bbb1be}.final-score b{font:700 25px 'Barlow Condensed';color:white}.mobile-controls{display:none;position:absolute;z-index:3;inset:auto 0 12px;padding:0 17px;justify-content:space-between;align-items:flex-end;pointer-events:none}.mobile-controls button{pointer-events:auto;border:1px solid #ffffff48;background:#1a1521b8;backdrop-filter:blur(6px);color:#fff;touch-action:none}.dpad{display:flex;flex-direction:column;align-items:center;gap:4px}.dpad button{width:40px;height:38px;border-radius:8px;font-size:14px}.dpad>div{display:flex;gap:4px}.mobile-actions{display:flex;align-items:flex-end;gap:8px}.mobile-actions button{width:48px;height:48px;border-radius:50%;font-size:18px;color:#ff697b}.mobile-actions button small{display:block;font:600 6px 'DM Sans';letter-spacing:.4px;color:#eee}.mobile-actions .action-attack{width:58px;height:58px;background:#a7223db8;border-color:#ff657688}.footer{position:absolute;left:4.15%;right:4.15%;bottom:13px;z-index:2;display:flex;justify-content:space-between;font-size:7px;letter-spacing:1.1px;color:#ada4af}.footer b{color:#f7445e}.footer-center{position:absolute;left:50%;transform:translateX(-50%)}.combat-toast{position:absolute;z-index:3;left:50%;top:32%;transform:translate(-50%,-50%);font:800 18px 'Barlow Condensed';letter-spacing:2px;color:#fff;text-shadow:0 0 17px #ff294f;opacity:0;transition:opacity .18s;pointer-events:none}.combat-toast.show{opacity:1}
@media(max-width:700px){.topbar{top:14px;left:15px;right:15px}.brand-name{font-size:14px}.brand-name span{display:none}.mission{top:52px;left:15px;transform:none;align-items:flex-start}.mission-name{font-size:13px}.mission-kicker{font-size:7px}.sound-button{height:30px;padding:0 8px}.sound-label{display:none}.hud{top:93px;left:15px;gap:12px}.portrait{width:37px;height:37px}.portrait>span{font-size:30px}.hero-info{min-width:112px}.hero-info strong{font-size:15px}.eyebrow{font-size:7px}.health-track{width:112px}.wave-card,.score-card{padding-left:9px;height:34px}.score-card{display:none}.wave-card strong{font-size:17px}.objective{top:154px;left:15px;padding:6px 8px}.objective small{font-size:8px}.controls-hint{display:none}.abilities{right:15px;bottom:110px;gap:4px}.ability{width:62px;height:54px}.ability-name{font-size:7px}.footer{left:15px;right:15px;bottom:7px;font-size:6px}.footer-center{display:none}.mobile-controls{display:flex}.intro-card{padding:26px 23px 23px}.title-mark{font-size:76px}.intro-card p{font-size:11px}.start-note{font-size:6px}.start-character{right:-5%;width:110px;opacity:.13}.end-card{padding:34px 22px}.end-card h1{font-size:31px}}
@media(max-height:570px) and (min-width:701px){.topbar{top:14px}.hud{top:75px}.objective{top:148px}.intro-card{transform:scale(.88)}.abilities{bottom:30px}.controls-hint{bottom:32px}.footer{bottom:7px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const startScreen = document.getElementById('startScreen');
  const endScreen = document.getElementById('endScreen');
  const keys = new Set();
  const touchDirs = new Set();
  const $ = id => document.getElementById(id);
  let W = 0, H = 0, dpr = 1, last = 0, running = false, soundOn = false;
  let player, enemies = [], particles = [], slashes = [], flowers = [], trees = [];
  let kills = 0, wave = 1, waveLeft = 0, spawnTimer = 0, qCooldown = 0, dashCooldown = 0, toastTimer = 0, shake = 0, audioCtx;
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const rand = (a,b) => a + Math.random()*(b-a);
  const dist = (a,b) => Math.hypot(a.x-b.x,a.y-b.y);
  function resize(){
    const r = canvas.getBoundingClientRect(); W = r.width; H = r.height; dpr = Math.min(devicePixelRatio || 1, 2);
    canvas.width = Math.round(W*dpr); canvas.height = Math.round(H*dpr); ctx.setTransform(dpr,0,0,dpr,0,0);
    if(player){ player.x = clamp(player.x,70,W-70); player.y = clamp(player.y,190,H-100); }
    makeDecor();
  }
  function makeDecor(){
    flowers=[];trees=[];
    for(let i=0;i<110;i++) flowers.push({x:rand(20,W-20),y:rand(150,H-5),s:rand(1,3),a:rand(.16,.55),c:Math.random()<.5?'#b43c67':'#ebc1c5'});
    for(let i=0;i<24;i++){
      const side=i%4, x=side===0?rand(-50,W+50):side===1?rand(-50,W+50):side===2?rand(-70,40):rand(W-40,W+70), y=side===0?rand(110,230):side===1?rand(H-180,H+60):rand(120,H-80);
      trees.push({x,y,r:rand(26,66),a:rand(.55,.95),seed:rand(0,20)});
    }
  }
  function init(){
    kills=0;wave=1;waveLeft=4;spawnTimer=.45;qCooldown=0;dashCooldown=0;particles=[];slashes=[];enemies=[];
    player={x:W*.5,y:H*.59,r:17,hp:100,face:0,speed:225,attack:0,attackCd:0,invuln:0,dashing:0,dx:0,dy:0,anim:0};
    for(let i=0;i<2;i++)spawnEnemy(); updateHud();
  }
  function start(){init();running=true;startScreen.classList.add('hidden');endScreen.classList.add('hidden');$('controlsHint').style.opacity='';$('objective').innerHTML='<span class="objective-icon">✦</span><span><b>OBJETIVO</b> <small>Elimina a los Grimm que acechan el bosque</small></span>';last=performance.now(); requestAnimationFrame(loop);}
  function end(win){running=false;$('endKicker').textContent=win?'MISIÓN COMPLETADA':'MISIÓN FALLIDA';$('endTitle').textContent=win?'¡VALE ESTÁ A SALVO!':'¡LA NOCHE TE VENCIÓ!';$('endCopy').textContent=win?'Los Grimm han sido derrotados. Buen trabajo, cazadora.':'Tu aura se ha agotado. Las cazadoras nunca se rinden.';$('finalKills').textContent=String(kills).padStart(2,'0');endScreen.classList.remove('hidden');}
  function showToast(text){const el=$('toast');el.textContent=text;el.classList.add('show');toastTimer=.75;}
  function updateHud(){ $('healthText').textContent=Math.ceil(player.hp);$('healthFill').style.width=player.hp+'%';$('killText').textContent=String(kills).padStart(2,'0');$('waveText').innerHTML=String(wave).padStart(2,'0')+' <i>/ 03</i>';document.querySelectorAll('.wave-dots span').forEach((el,i)=>el.classList.toggle('active',i<wave));$('qCd').textContent=qCooldown>0?qCooldown.toFixed(1)+'s':'LISTO';$('eCd').textContent=dashCooldown>0?dashCooldown.toFixed(1)+'s':'LISTO';}
  function spawnEnemy(){
    if(!player)return; const angle=rand(0,Math.PI*2), edge=rand(.38,.47), x=clamp(player.x+Math.cos(angle)*W*edge,35,W-35),y=clamp(player.y+Math.sin(angle)*H*edge,190,H-35);
    const boss=wave===3&&waveLeft===1;
    enemies.push({x,y,r:boss?31:17,hp:boss?9:(wave===1?2:3),maxHp:boss?9:(wave===1?2:3),speed:boss?63:rand(65,91)+(wave-1)*12,attack:0,hit:0,phase:rand(0,8),boss,dead:false});
  }
  function burst(x,y,color,n=8,power=150){for(let i=0;i<n;i++){let a=rand(0,Math.PI*2),s=rand(power*.25,power);particles.push({x,y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,life:rand(.22,.62),max:.62,size:rand(1.5,4),color});}}
  function sound(freq=220,dur=.07,type='sawtooth'){if(!soundOn)return;try{audioCtx ||= new (window.AudioContext||window.webkitAudioContext)();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+dur);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+dur);}catch{}}
  function attack(){if(!running||player.attackCd>0)return;player.attack=.24;player.attackCd=.34;const nearest=enemies.filter(e=>!e.dead).sort((a,b)=>dist(player,a)-dist(player,b))[0];if(nearest&&dist(player,nearest)<260)player.face=Math.atan2(nearest.y-player.y,nearest.x-player.x);slashes.push({x:player.x,y:player.y,a:player.face,life:.22,max:.22,r:70,wide:.95});burst(player.x+Math.cos(player.face)*39,player.y+Math.sin(player.face)*39,'#ff4965',5,85);sound(270,.09,'triangle');
    for(const e of enemies){if(e.dead)continue;const d=dist(player,e),a=Math.atan2(e.y-player.y,e.x-player.x),diff=Math.atan2(Math.sin(a-player.face),Math.cos(a-player.face));if(d<(e.boss?104:88)&&Math.abs(diff)<1.25){hitEnemy(e,1,player.face);}}
  }
  function hitEnemy(e,damage,angle){e.hp-=damage;e.hit=.18;e.x+=Math.cos(angle)*12;e.y+=Math.sin(angle)*12;burst(e.x,e.y,e.boss?'#ff3656':'#c6d9db',7,125);sound(135,.08,'square');if(e.hp<=0){e.dead=true;kills++;burst(e.x,e.y,'#e93452',17,205);updateHud();if(kills===4)showToast('¡PRIMERA OLEADA SUPERADA!');if(kills===9)showToast('¡EL ALFA HA LLEGADO!');}}
  function special(){if(!running||qCooldown>0)return;qCooldown=7;player.attack=.55;player.invuln=.45;slashes.push({x:player.x,y:player.y,a:0,life:.55,max:.55,r:205,wide:Math.PI*2});burst(player.x,player.y,'#f93659',28,260);shake=10;sound(490,.26,'sawtooth');showToast('SEMBLANTE: PETAL BURST');for(const e of enemies){if(!e.dead&&dist(player,e)<205)hitEnemy(e,e.boss?3:2,Math.atan2(e.y-player.y,e.x-player.x));}}
  function dash(){if(!running||dashCooldown>0)return;dashCooldown=2.2;let x=(keys.has('d')||keys.has('ArrowRight')||touchDirs.has('right')?1:0)-(keys.has('a')||keys.has('ArrowLeft')||touchDirs.has('left')?1:0),y=(keys.has('s')||keys.has('ArrowDown')||touchDirs.has('down')?1:0)-(keys.has('w')||keys.has('ArrowUp')||touchDirs.has('up')?1:0);if(!x&&!y){x=Math.cos(player.face);y=Math.sin(player.face)}let l=Math.hypot(x,y)||1;player.dx=x/l;player.dy=y/l;player.dashing=.2;player.invuln=.35;for(let i=0;i<10;i++)particles.push({x:player.x+rand(-9,9),y:player.y+rand(-12,12),vx:-player.dx*rand(70,180),vy:-player.dy*rand(70,180),life:rand(.2,.48),max:.48,size:rand(3,8),color:'#e83354'});sound(620,.12,'triangle');}
  function hurt(dmg){if(player.invuln>0)return;player.hp=Math.max(0,player.hp-dmg);player.invuln=.85;shake=7;burst(player.x,player.y,'#ff5267',12,130);updateHud();sound(90,.2,'sawtooth');if(player.hp<=0)end(false);}
  function update(dt){
    if(!running)return;dt=Math.min(dt,.035);player.anim+=dt;player.attackCd=Math.max(0,player.attackCd-dt);player.attack=Math.max(0,player.attack-dt);player.invuln=Math.max(0,player.invuln-dt);player.dashing=Math.max(0,player.dashing-dt);qCooldown=Math.max(0,qCooldown-dt);dashCooldown=Math.max(0,dashCooldown-dt);toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show');
    let vx=(keys.has('d')||keys.has('ArrowRight')||touchDirs.has('right')?1:0)-(keys.has('a')||keys.has('ArrowLeft')||touchDirs.has('left')?1:0),vy=(keys.has('s')||keys.has('ArrowDown')||touchDirs.has('down')?1:0)-(keys.has('w')||keys.has('ArrowUp')||touchDirs.has('up')?1:0),len=Math.hypot(vx,vy);
    if(len){vx/=len;vy/=len;player.face=Math.atan2(vy,vx);}
    if(player.dashing){player.x+=player.dx*790*dt;player.y+=player.dy*790*dt;}else{player.x+=vx*player.speed*dt;player.y+=vy*player.speed*dt;}
    player.x=clamp(player.x,35,W-35);player.y=clamp(player.y,182,H-39);
    spawnTimer-=dt;if(spawnTimer<=0&&waveLeft>0){spawnEnemy();waveLeft--;spawnTimer=wave===1?1.4:1.15;}
    for(const e of enemies){if(e.dead)continue;e.phase+=dt*4;e.hit=Math.max(0,e.hit-dt);const dx=player.x-e.x,dy=player.y-e.y,d=Math.hypot(dx,dy)||1;if(d>(e.r+player.r+7)){e.x+=dx/d*e.speed*dt;e.y+=dy/d*e.speed*dt;}else{e.attack-=dt;if(e.attack<=0){e.attack=e.boss?1.05:1.35;hurt(e.boss?13:8);}}}
    enemies=enemies.filter(e=>!e.dead||Math.random()>.94);
    if(waveLeft===0&&enemies.length===0){if(wave<3){wave++;waveLeft=wave===2?5:5;spawnTimer=.7;updateHud();$('objective').innerHTML='<span class="objective-icon">✦</span><span><b>ALERTA · OLEADA '+String(wave).padStart(2,'0')+'</b> <small>¡Más Grimm se aproximan!</small></span>';showToast(wave===3?'¡CUIDADO CON EL GRIMM ALFA!':'¡NUEVA OLEADA!');}else{end(true);}}
